-- =====================================================================
-- Academia New Force — Entrega 2 — MySQL 8
-- Passo 1 e 2: CREATE DATABASE e CREATE TABLE; passo 3: constraints (PK, FK, NOT NULL, UNIQUE, CHECK, DEFAULT)
-- =====================================================================
DROP DATABASE IF EXISTS new_force_db;
CREATE DATABASE new_force_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE new_force_db;
SET NAMES utf8mb4;

CREATE TABLE ALUNO (
  ID_ALUNO INT AUTO_INCREMENT PRIMARY KEY,
  ID_CPF varchar(11) NOT NULL,
  ID_RG varchar(20) NOT NULL,
  NM_ALUNO varchar(120) NOT NULL,
  DT_NASCIMENTO DATE NOT NULL,
  NR_CELULAR varchar(20) NOT NULL,
  CD_CEP char(8) NOT NULL,
  DS_EMAIL varchar(120) NOT NULL,
  DS_RESTRICAO_PESSOAL TEXT NULL,
  NR_TELEFONE_RESPONSAVEL varchar(20) NULL,
  TP_SITUACAO varchar(10) NOT NULL DEFAULT 'ativo',
  DS_SENHA_ACESSO_HASH varchar(255) NULL,
  DS_BIOMETRIA_FACIAL BLOB NULL,
  CONSTRAINT uq_aluno_id_cpf UNIQUE (ID_CPF),
  CONSTRAINT ck_aluno_tp_situacao CHECK (TP_SITUACAO IN ('ativo', 'inativo', 'bloqueado')),
  CONSTRAINT ck_aluno_regra CHECK (LENGTH(ID_CPF) = 11 AND LENGTH(CD_CEP) = 8)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PLANO (
  ID_PLANO INT AUTO_INCREMENT PRIMARY KEY,
  TP_PLANO varchar(12) NOT NULL,
  QT_MESES INT NULL,
  VL_PLANO decimal(10,2) NOT NULL,
  TP_COBRANCA varchar(16) NOT NULL,
  CONSTRAINT ck_plano_tp_plano CHECK (TP_PLANO IN ('mensal', 'trimestral', 'semestral', 'anual', 'diaria')),
  CONSTRAINT ck_plano_qt_meses CHECK (QT_MESES >= 0),
  CONSTRAINT ck_plano_vl_plano CHECK (VL_PLANO > 0),
  CONSTRAINT ck_plano_tp_cobranca CHECK (TP_COBRANCA IN ('recorrente', 'por_contrato', 'na_hora'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PROMOCAO (
  ID_PROMOCAO INT AUTO_INCREMENT PRIMARY KEY,
  DS_PROMOCAO varchar(200) NOT NULL,
  DS_BENEFICIO varchar(200) NOT NULL,
  DT_MES_VIGENCIA DATE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE CONTRATO (
  ID_CONTRATO INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NOT NULL,
  ID_PLANO INT NOT NULL,
  ID_PROMOCAO INT NULL,
  DT_INICIO DATE NOT NULL,
  DT_FIM DATE NOT NULL,
  TP_SITUACAO varchar(10) NOT NULL DEFAULT 'vigente',
  IN_TAXA_MATRICULA_COBRADA BOOLEAN NOT NULL DEFAULT 0,
  CONSTRAINT fk_contrato_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT fk_contrato_plano FOREIGN KEY (ID_PLANO) REFERENCES PLANO(ID_PLANO),
  CONSTRAINT fk_contrato_promocao FOREIGN KEY (ID_PROMOCAO) REFERENCES PROMOCAO(ID_PROMOCAO),
  CONSTRAINT ck_contrato_tp_situacao CHECK (TP_SITUACAO IN ('vigente', 'trancado', 'cancelado', 'encerrado')),
  CONSTRAINT ck_contrato_regra CHECK (DT_FIM >= DT_INICIO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TRANCAMENTO (
  ID_TRANCAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_CONTRATO INT NOT NULL,
  DT_INICIO DATE NOT NULL,
  DT_FIM DATE NOT NULL,
  CONSTRAINT fk_trancamento_contrato FOREIGN KEY (ID_CONTRATO) REFERENCES CONTRATO(ID_CONTRATO),
  CONSTRAINT ck_trancamento_regra CHECK (DT_FIM >= DT_INICIO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE CANCELAMENTO (
  ID_CANCELAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_CONTRATO INT NOT NULL,
  DT_CANCELAMENTO DATE NOT NULL,
  VL_MULTA decimal(10,2) NOT NULL,
  QT_MESES_UTILIZADOS INT NOT NULL,
  CONSTRAINT fk_cancelamento_contrato FOREIGN KEY (ID_CONTRATO) REFERENCES CONTRATO(ID_CONTRATO),
  CONSTRAINT uq_cancelamento_contrato UNIQUE (ID_CONTRATO),
  CONSTRAINT ck_cancelamento_vl_multa CHECK (VL_MULTA >= 0),
  CONSTRAINT ck_cancelamento_qt_meses_utilizados CHECK (QT_MESES_UTILIZADOS >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE NOTIFICACAO (
  ID_NOTIFICACAO INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NOT NULL,
  DT_ENVIO DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  TP_NOTIFICACAO varchar(14) NOT NULL,
  DS_CANAL varchar(30) NULL,
  CONSTRAINT fk_notificacao_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT ck_notificacao_tp_notificacao CHECK (TP_NOTIFICACAO IN ('termino_plano', 'novo_treino'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PERFIL (
  ID_PERFIL INT AUTO_INCREMENT PRIMARY KEY,
  NM_PERFIL varchar(20) NOT NULL,
  CONSTRAINT uq_perfil_nm_perfil UNIQUE (NM_PERFIL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PERMISSAO (
  ID_PERMISSAO INT AUTO_INCREMENT PRIMARY KEY,
  NM_MODULO varchar(40) NOT NULL,
  TP_ACAO varchar(20) NOT NULL,
  CONSTRAINT uq_permissao_negocio UNIQUE (NM_MODULO, TP_ACAO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PERFIL_PERMISSAO (
  ID_PERFIL_PERMISSAO INT AUTO_INCREMENT PRIMARY KEY,
  ID_PERFIL INT NOT NULL,
  ID_PERMISSAO INT NOT NULL,
  CONSTRAINT fk_perfil_permissao_perfil FOREIGN KEY (ID_PERFIL) REFERENCES PERFIL(ID_PERFIL),
  CONSTRAINT fk_perfil_permissao_permissao FOREIGN KEY (ID_PERMISSAO) REFERENCES PERMISSAO(ID_PERMISSAO),
  CONSTRAINT uq_perfil_permissao_negocio UNIQUE (ID_PERFIL, ID_PERMISSAO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE FUNCIONARIO (
  ID_FUNCIONARIO INT AUTO_INCREMENT PRIMARY KEY,
  ID_PERFIL INT NOT NULL,
  ID_MATRICULA varchar(20) NOT NULL,
  NM_FUNCIONARIO varchar(120) NOT NULL,
  DS_SENHA_HASH varchar(255) NOT NULL,
  DS_BIOMETRIA_FACIAL BLOB NULL,
  IN_ATIVO BOOLEAN NOT NULL DEFAULT 1,
  CONSTRAINT fk_funcionario_perfil FOREIGN KEY (ID_PERFIL) REFERENCES PERFIL(ID_PERFIL),
  CONSTRAINT uq_funcionario_id_matricula UNIQUE (ID_MATRICULA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PROFESSOR (
  ID_PROFESSOR INT AUTO_INCREMENT PRIMARY KEY,
  ID_FUNCIONARIO INT NOT NULL,
  QT_MESES_EXPERIENCIA INT NOT NULL,
  DS_RESULTADO_ENTREVISTA varchar(200) NOT NULL,
  DS_CONHECIMENTO_AREA TEXT NOT NULL,
  CONSTRAINT fk_professor_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT uq_professor_funcionario UNIQUE (ID_FUNCIONARIO),
  CONSTRAINT ck_professor_qt_meses_experiencia CHECK (QT_MESES_EXPERIENCIA >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ESCALA_TRABALHO (
  ID_ESCALA_TRABALHO INT AUTO_INCREMENT PRIMARY KEY,
  ID_FUNCIONARIO INT NOT NULL,
  TP_TURNO varchar(6) NOT NULL,
  IN_REFORCO BOOLEAN NOT NULL DEFAULT 0,
  QT_HORAS_DIA INT NULL,
  CONSTRAINT fk_escala_trabalho_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT ck_escala_trabalho_tp_turno CHECK (TP_TURNO IN ('manha', 'tarde', 'noite')),
  CONSTRAINT ck_escala_trabalho_qt_horas_dia CHECK (QT_HORAS_DIA >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PONTO (
  ID_PONTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_FUNCIONARIO INT NOT NULL,
  DT_ENTRADA DATETIME NOT NULL,
  DT_SAIDA DATETIME NULL,
  CONSTRAINT fk_ponto_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT uq_ponto_negocio UNIQUE (ID_FUNCIONARIO, DT_ENTRADA),
  CONSTRAINT ck_ponto_regra CHECK (DT_SAIDA IS NULL OR DT_SAIDA >= DT_ENTRADA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE AVALIACAO_FISICA (
  ID_AVALIACAO_FISICA INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NOT NULL,
  ID_PROFESSOR INT NOT NULL,
  DT_AVALIACAO DATETIME NOT NULL,
  TP_METODO varchar(15) NOT NULL,
  VL_GORDURA_ACUMULADA decimal(5,2) NULL,
  VL_MASSA_MAGRA decimal(5,2) NULL,
  VL_AGUA decimal(5,2) NULL,
  DS_DOBRAS_CUTANEAS TEXT NULL,
  TP_SITUACAO varchar(9) NOT NULL DEFAULT 'agendada',
  CONSTRAINT fk_avaliacao_fisica_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT fk_avaliacao_fisica_professor FOREIGN KEY (ID_PROFESSOR) REFERENCES PROFESSOR(ID_PROFESSOR),
  CONSTRAINT ck_avaliacao_fisica_tp_metodo CHECK (TP_METODO IN ('bioimpedancia', 'adipometro')),
  CONSTRAINT ck_avaliacao_fisica_vl_gordura_acumulada CHECK (VL_GORDURA_ACUMULADA >= 0),
  CONSTRAINT ck_avaliacao_fisica_vl_massa_magra CHECK (VL_MASSA_MAGRA >= 0),
  CONSTRAINT ck_avaliacao_fisica_vl_agua CHECK (VL_AGUA >= 0),
  CONSTRAINT ck_avaliacao_fisica_tp_situacao CHECK (TP_SITUACAO IN ('agendada', 'realizada'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE FICHA_TREINO (
  ID_FICHA_TREINO INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NOT NULL,
  ID_PROFESSOR INT NOT NULL,
  DT_CRIACAO DATE NOT NULL,
  DS_DIFICULDADES TEXT NULL,
  DT_TROCA_PREVISTA DATE NOT NULL,
  CONSTRAINT fk_ficha_treino_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT fk_ficha_treino_professor FOREIGN KEY (ID_PROFESSOR) REFERENCES PROFESSOR(ID_PROFESSOR)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TREINO (
  ID_TREINO INT AUTO_INCREMENT PRIMARY KEY,
  ID_FICHA_TREINO INT NOT NULL,
  TP_LETRA char(1) NOT NULL,
  CONSTRAINT fk_treino_ficha_treino FOREIGN KEY (ID_FICHA_TREINO) REFERENCES FICHA_TREINO(ID_FICHA_TREINO),
  CONSTRAINT ck_treino_tp_letra CHECK (TP_LETRA IN ('a', 'b', 'c')),
  CONSTRAINT uq_treino_negocio UNIQUE (ID_FICHA_TREINO, TP_LETRA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE EXERCICIO (
  ID_EXERCICIO INT AUTO_INCREMENT PRIMARY KEY,
  NM_EXERCICIO varchar(100) NOT NULL,
  DS_GRUPO_MUSCULAR varchar(60) NOT NULL,
  DS_VIDEO_EXECUCAO varchar(255) NULL,
  NM_APARELHO varchar(100) NULL,
  CONSTRAINT uq_exercicio_nm_exercicio UNIQUE (NM_EXERCICIO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TREINO_EXERCICIO (
  ID_TREINO_EXERCICIO INT AUTO_INCREMENT PRIMARY KEY,
  ID_TREINO INT NOT NULL,
  ID_EXERCICIO INT NOT NULL,
  QT_ORDEM INT NOT NULL,
  QT_SERIES INT NOT NULL,
  QT_REPETICOES INT NOT NULL,
  CONSTRAINT fk_treino_exercicio_treino FOREIGN KEY (ID_TREINO) REFERENCES TREINO(ID_TREINO),
  CONSTRAINT fk_treino_exercicio_exercicio FOREIGN KEY (ID_EXERCICIO) REFERENCES EXERCICIO(ID_EXERCICIO),
  CONSTRAINT ck_treino_exercicio_qt_ordem CHECK (QT_ORDEM > 0),
  CONSTRAINT ck_treino_exercicio_qt_series CHECK (QT_SERIES > 0),
  CONSTRAINT ck_treino_exercicio_qt_repeticoes CHECK (QT_REPETICOES > 0),
  CONSTRAINT uq_treino_exercicio_negocio UNIQUE (ID_TREINO, QT_ORDEM)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE REGISTRO_CARGA (
  ID_REGISTRO_CARGA INT AUTO_INCREMENT PRIMARY KEY,
  ID_TREINO_EXERCICIO INT NOT NULL,
  DT_REGISTRO DATE NOT NULL,
  VL_CARGA decimal(6,2) NOT NULL,
  CONSTRAINT fk_registro_carga_treino_exercicio FOREIGN KEY (ID_TREINO_EXERCICIO) REFERENCES TREINO_EXERCICIO(ID_TREINO_EXERCICIO),
  CONSTRAINT ck_registro_carga_vl_carga CHECK (VL_CARGA >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE MODALIDADE (
  ID_MODALIDADE INT AUTO_INCREMENT PRIMARY KEY,
  NM_MODALIDADE varchar(20) NOT NULL,
  CONSTRAINT uq_modalidade_nm_modalidade UNIQUE (NM_MODALIDADE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE AULA_COLETIVA (
  ID_AULA_COLETIVA INT AUTO_INCREMENT PRIMARY KEY,
  ID_MODALIDADE INT NOT NULL,
  ID_PROFESSOR INT NOT NULL,
  TP_DIA_SEMANA varchar(3) NOT NULL,
  HR_INICIO TIME NOT NULL,
  QT_CAPACIDADE_MAXIMA INT NOT NULL,
  CONSTRAINT fk_aula_coletiva_modalidade FOREIGN KEY (ID_MODALIDADE) REFERENCES MODALIDADE(ID_MODALIDADE),
  CONSTRAINT fk_aula_coletiva_professor FOREIGN KEY (ID_PROFESSOR) REFERENCES PROFESSOR(ID_PROFESSOR),
  CONSTRAINT ck_aula_coletiva_tp_dia_semana CHECK (TP_DIA_SEMANA IN ('seg', 'ter', 'qua', 'qui', 'sex', 'sab')),
  CONSTRAINT ck_aula_coletiva_qt_capacidade_maxima CHECK (QT_CAPACIDADE_MAXIMA > 0),
  CONSTRAINT uq_aula_coletiva_negocio UNIQUE (ID_MODALIDADE, TP_DIA_SEMANA, HR_INICIO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE AGENDAMENTO_AULA (
  ID_AGENDAMENTO_AULA INT AUTO_INCREMENT PRIMARY KEY,
  ID_AULA_COLETIVA INT NOT NULL,
  ID_ALUNO INT NOT NULL,
  DT_AULA DATETIME NOT NULL,
  DT_AGENDAMENTO DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  IN_PRESENTE BOOLEAN NULL,
  CONSTRAINT fk_agendamento_aula_aula_coletiva FOREIGN KEY (ID_AULA_COLETIVA) REFERENCES AULA_COLETIVA(ID_AULA_COLETIVA),
  CONSTRAINT fk_agendamento_aula_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT uq_agendamento_aula_negocio UNIQUE (ID_ALUNO, ID_AULA_COLETIVA, DT_AULA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PRODUTO (
  ID_PRODUTO INT AUTO_INCREMENT PRIMARY KEY,
  NM_PRODUTO varchar(100) NOT NULL,
  TP_CATEGORIA varchar(40) NOT NULL,
  VL_PRECO decimal(10,2) NOT NULL,
  CONSTRAINT uq_produto_nm_produto UNIQUE (NM_PRODUTO),
  CONSTRAINT ck_produto_vl_preco CHECK (VL_PRECO > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE FORNECEDOR (
  ID_FORNECEDOR INT AUTO_INCREMENT PRIMARY KEY,
  NM_FORNECEDOR varchar(120) NOT NULL,
  TP_FORNECEDOR varchar(12) NOT NULL,
  NR_CONTATO varchar(20) NULL,
  CONSTRAINT uq_fornecedor_nm_fornecedor UNIQUE (NM_FORNECEDOR),
  CONSTRAINT ck_fornecedor_tp_fornecedor CHECK (TP_FORNECEDOR IN ('suplementos', 'equipamentos', 'pecas'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE VENDA (
  ID_VENDA INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NULL,
  ID_FUNCIONARIO INT NOT NULL,
  DT_VENDA DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  VL_TOTAL decimal(10,2) NOT NULL,
  CONSTRAINT fk_venda_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT fk_venda_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT ck_venda_vl_total CHECK (VL_TOTAL >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ITEM_VENDA (
  ID_ITEM_VENDA INT AUTO_INCREMENT PRIMARY KEY,
  ID_VENDA INT NOT NULL,
  ID_PRODUTO INT NOT NULL,
  QT_VENDIDA INT NOT NULL,
  VL_PRECO_UNITARIO decimal(10,2) NOT NULL,
  CONSTRAINT fk_item_venda_venda FOREIGN KEY (ID_VENDA) REFERENCES VENDA(ID_VENDA),
  CONSTRAINT fk_item_venda_produto FOREIGN KEY (ID_PRODUTO) REFERENCES PRODUTO(ID_PRODUTO),
  CONSTRAINT ck_item_venda_qt_vendida CHECK (QT_VENDIDA > 0),
  CONSTRAINT ck_item_venda_vl_preco_unitario CHECK (VL_PRECO_UNITARIO >= 0),
  CONSTRAINT uq_item_venda_negocio UNIQUE (ID_VENDA, ID_PRODUTO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE EQUIPAMENTO (
  ID_EQUIPAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_FORNECEDOR INT NULL,
  NM_EQUIPAMENTO varchar(100) NOT NULL,
  TP_CATEGORIA varchar(12) NOT NULL,
  DS_LOCALIZACAO varchar(60) NOT NULL,
  DT_AQUISICAO DATE NULL,
  DT_FIM_GARANTIA DATE NULL,
  TP_SITUACAO varchar(11) NOT NULL DEFAULT 'operacional',
  CONSTRAINT fk_equipamento_fornecedor FOREIGN KEY (ID_FORNECEDOR) REFERENCES FORNECEDOR(ID_FORNECEDOR),
  CONSTRAINT ck_equipamento_tp_categoria CHECK (TP_CATEGORIA IN ('maquina', 'peso_livre', 'esteira', 'escada', 'bicicleta')),
  CONSTRAINT ck_equipamento_tp_situacao CHECK (TP_SITUACAO IN ('operacional', 'interditado')),
  CONSTRAINT ck_equipamento_regra CHECK (DT_AQUISICAO IS NULL OR DT_FIM_GARANTIA IS NULL OR DT_FIM_GARANTIA >= DT_AQUISICAO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ROTINA_MANUTENCAO (
  ID_ROTINA_MANUTENCAO INT AUTO_INCREMENT PRIMARY KEY,
  DS_ROTINA varchar(200) NOT NULL,
  TP_CATEGORIA_ALVO varchar(12) NOT NULL,
  TP_PERIODICIDADE varchar(10) NOT NULL,
  TP_EXECUTOR varchar(20) NOT NULL,
  CONSTRAINT ck_rotina_manutencao_tp_categoria_alvo CHECK (TP_CATEGORIA_ALVO IN ('maquina', 'peso_livre', 'esteira', 'escada', 'bicicleta')),
  CONSTRAINT ck_rotina_manutencao_tp_periodicidade CHECK (TP_PERIODICIDADE IN ('diaria', 'semanal', 'quinzenal', 'mensal')),
  CONSTRAINT ck_rotina_manutencao_tp_executor CHECK (TP_EXECUTOR IN ('equipe_interna', 'empresa_terceirizada'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE INSPECAO_EQUIPAMENTO (
  ID_INSPECAO_EQUIPAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_EQUIPAMENTO INT NOT NULL,
  ID_FUNCIONARIO INT NULL,
  DT_INSPECAO DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  TP_COMPONENTE varchar(10) NOT NULL,
  TP_CONDICAO varchar(8) NOT NULL,
  DS_OBSERVACAO varchar(200) NULL,
  CONSTRAINT fk_inspecao_equipamento_equipamento FOREIGN KEY (ID_EQUIPAMENTO) REFERENCES EQUIPAMENTO(ID_EQUIPAMENTO),
  CONSTRAINT fk_inspecao_equipamento_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT ck_inspecao_equipamento_tp_componente CHECK (TP_COMPONENTE IN ('cabo', 'polia', 'estofado', 'estrutura')),
  CONSTRAINT ck_inspecao_equipamento_tp_condicao CHECK (TP_CONDICAO IN ('boa', 'atencao', 'ruim'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE INCIDENTE_SEGURANCA (
  ID_INCIDENTE_SEGURANCA INT AUTO_INCREMENT PRIMARY KEY,
  ID_EQUIPAMENTO INT NOT NULL,
  ID_ALUNO INT NULL,
  DT_INCIDENTE DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DS_INCIDENTE TEXT NOT NULL,
  TP_GRAVIDADE varchar(8) NOT NULL,
  CONSTRAINT fk_incidente_seguranca_equipamento FOREIGN KEY (ID_EQUIPAMENTO) REFERENCES EQUIPAMENTO(ID_EQUIPAMENTO),
  CONSTRAINT fk_incidente_seguranca_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT ck_incidente_seguranca_tp_gravidade CHECK (TP_GRAVIDADE IN ('leve', 'moderada', 'grave'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ASSISTENCIA_TECNICA (
  ID_ASSISTENCIA_TECNICA INT AUTO_INCREMENT PRIMARY KEY,
  NM_EMPRESA varchar(120) NOT NULL,
  NR_CONTATO varchar(20) NULL,
  DT_INICIO_CONTRATO DATE NULL,
  DT_FIM_CONTRATO DATE NULL,
  CONSTRAINT uq_assistencia_tecnica_nm_empresa UNIQUE (NM_EMPRESA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE COBRANCA (
  ID_COBRANCA INT AUTO_INCREMENT PRIMARY KEY,
  ID_CONTRATO INT NULL,
  ID_VENDA INT NULL,
  VL_COBRANCA decimal(10,2) NOT NULL,
  DT_VENCIMENTO DATE NOT NULL,
  TP_COBRANCA varchar(16) NOT NULL,
  TP_SITUACAO varchar(10) NOT NULL DEFAULT 'em_aberto',
  CONSTRAINT fk_cobranca_contrato FOREIGN KEY (ID_CONTRATO) REFERENCES CONTRATO(ID_CONTRATO),
  CONSTRAINT fk_cobranca_venda FOREIGN KEY (ID_VENDA) REFERENCES VENDA(ID_VENDA),
  CONSTRAINT ck_cobranca_vl_cobranca CHECK (VL_COBRANCA > 0),
  CONSTRAINT ck_cobranca_tp_cobranca CHECK (TP_COBRANCA IN ('recorrente', 'por_contrato', 'nao_recorrente')),
  CONSTRAINT ck_cobranca_tp_situacao CHECK (TP_SITUACAO IN ('em_aberto', 'paga', 'atrasada')),
  CONSTRAINT ck_cobranca_regra CHECK ((ID_CONTRATO IS NOT NULL AND ID_VENDA IS NULL) OR (ID_CONTRATO IS NULL AND ID_VENDA IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PAGAMENTO (
  ID_PAGAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_COBRANCA INT NOT NULL,
  DT_PAGAMENTO DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  VL_PAGO decimal(10,2) NOT NULL,
  TP_FORMA varchar(10) NOT NULL,
  CONSTRAINT fk_pagamento_cobranca FOREIGN KEY (ID_COBRANCA) REFERENCES COBRANCA(ID_COBRANCA),
  CONSTRAINT ck_pagamento_vl_pago CHECK (VL_PAGO > 0),
  CONSTRAINT ck_pagamento_tp_forma CHECK (TP_FORMA IN ('credito', 'debito', 'pix', 'dinheiro'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE NOTA_FISCAL (
  ID_NOTA_FISCAL INT AUTO_INCREMENT PRIMARY KEY,
  ID_PAGAMENTO INT NOT NULL,
  NR_NOTA varchar(20) NOT NULL,
  DT_EMISSAO DATE NOT NULL,
  IN_ENVIADA_WHATSAPP BOOLEAN NOT NULL DEFAULT 0,
  CONSTRAINT fk_nota_fiscal_pagamento FOREIGN KEY (ID_PAGAMENTO) REFERENCES PAGAMENTO(ID_PAGAMENTO),
  CONSTRAINT uq_nota_fiscal_pagamento UNIQUE (ID_PAGAMENTO),
  CONSTRAINT uq_nota_fiscal_nr_nota UNIQUE (NR_NOTA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE REGISTRO_ACESSO (
  ID_REGISTRO_ACESSO INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO INT NOT NULL,
  ID_FUNCIONARIO INT NULL,
  DT_ACESSO DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  TP_METODO varchar(8) NOT NULL,
  TP_RESULTADO varchar(10) NOT NULL,
  DS_MOTIVO_BLOQUEIO varchar(100) NULL,
  CONSTRAINT fk_registro_acesso_aluno FOREIGN KEY (ID_ALUNO) REFERENCES ALUNO(ID_ALUNO),
  CONSTRAINT fk_registro_acesso_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT ck_registro_acesso_tp_metodo CHECK (TP_METODO IN ('facial', 'senha', 'manual')),
  CONSTRAINT ck_registro_acesso_tp_resultado CHECK (TP_RESULTADO IN ('permitido', 'negado')),
  CONSTRAINT uq_registro_acesso_negocio UNIQUE (ID_ALUNO, DT_ACESSO)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE COMPRA (
  ID_COMPRA INT AUTO_INCREMENT PRIMARY KEY,
  ID_FORNECEDOR INT NOT NULL,
  DT_COMPRA DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  VL_TOTAL decimal(10,2) NOT NULL,
  CONSTRAINT fk_compra_fornecedor FOREIGN KEY (ID_FORNECEDOR) REFERENCES FORNECEDOR(ID_FORNECEDOR),
  CONSTRAINT ck_compra_vl_total CHECK (VL_TOTAL >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE EXECUCAO_MANUTENCAO (
  ID_EXECUCAO_MANUTENCAO INT AUTO_INCREMENT PRIMARY KEY,
  ID_EQUIPAMENTO INT NOT NULL,
  ID_ROTINA_MANUTENCAO INT NOT NULL,
  ID_ASSISTENCIA_TECNICA INT NULL,
  DT_EXECUCAO DATE NOT NULL,
  VL_CUSTO decimal(10,2) NULL,
  DS_RESULTADO TEXT NULL,
  CONSTRAINT fk_execucao_manutencao_equipamento FOREIGN KEY (ID_EQUIPAMENTO) REFERENCES EQUIPAMENTO(ID_EQUIPAMENTO),
  CONSTRAINT fk_execucao_manutencao_rotina_manutencao FOREIGN KEY (ID_ROTINA_MANUTENCAO) REFERENCES ROTINA_MANUTENCAO(ID_ROTINA_MANUTENCAO),
  CONSTRAINT fk_execucao_manutencao_assistencia_tecnica FOREIGN KEY (ID_ASSISTENCIA_TECNICA) REFERENCES ASSISTENCIA_TECNICA(ID_ASSISTENCIA_TECNICA),
  CONSTRAINT ck_execucao_manutencao_vl_custo CHECK (VL_CUSTO >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE CHAMADO_TECNICO (
  ID_CHAMADO_TECNICO INT AUTO_INCREMENT PRIMARY KEY,
  ID_EQUIPAMENTO INT NOT NULL,
  ID_ASSISTENCIA_TECNICA INT NULL,
  ID_FUNCIONARIO INT NULL,
  DT_ABERTURA DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DS_DIAGNOSTICO_INICIAL TEXT NOT NULL,
  DT_VISITA DATETIME NULL,
  VL_CUSTO_SERVICO decimal(10,2) NULL,
  IN_TESTE_CARGA_APROVADO BOOLEAN NULL,
  DT_LIBERACAO DATETIME NULL,
  TP_SITUACAO varchar(14) NOT NULL DEFAULT 'aberto',
  CONSTRAINT fk_chamado_tecnico_equipamento FOREIGN KEY (ID_EQUIPAMENTO) REFERENCES EQUIPAMENTO(ID_EQUIPAMENTO),
  CONSTRAINT fk_chamado_tecnico_assistencia_tecnica FOREIGN KEY (ID_ASSISTENCIA_TECNICA) REFERENCES ASSISTENCIA_TECNICA(ID_ASSISTENCIA_TECNICA),
  CONSTRAINT fk_chamado_tecnico_funcionario FOREIGN KEY (ID_FUNCIONARIO) REFERENCES FUNCIONARIO(ID_FUNCIONARIO),
  CONSTRAINT ck_chamado_tecnico_vl_custo_servico CHECK (VL_CUSTO_SERVICO >= 0),
  CONSTRAINT ck_chamado_tecnico_tp_situacao CHECK (TP_SITUACAO IN ('aberto', 'em_atendimento', 'concluido')),
  CONSTRAINT ck_chamado_tecnico_regra CHECK (DT_LIBERACAO IS NULL OR DT_LIBERACAO >= DT_ABERTURA)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PECA_TROCADA (
  ID_PECA_TROCADA INT AUTO_INCREMENT PRIMARY KEY,
  ID_CHAMADO_TECNICO INT NOT NULL,
  ID_FORNECEDOR INT NULL,
  NM_PECA varchar(100) NOT NULL,
  QT_PECA INT NOT NULL,
  VL_CUSTO_UNITARIO decimal(10,2) NOT NULL,
  IN_ORIGINAL BOOLEAN NOT NULL DEFAULT 1,
  CONSTRAINT fk_peca_trocada_chamado_tecnico FOREIGN KEY (ID_CHAMADO_TECNICO) REFERENCES CHAMADO_TECNICO(ID_CHAMADO_TECNICO),
  CONSTRAINT fk_peca_trocada_fornecedor FOREIGN KEY (ID_FORNECEDOR) REFERENCES FORNECEDOR(ID_FORNECEDOR),
  CONSTRAINT ck_peca_trocada_qt_peca CHECK (QT_PECA > 0),
  CONSTRAINT ck_peca_trocada_vl_custo_unitario CHECK (VL_CUSTO_UNITARIO >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE LOTE_PRODUTO (
  ID_LOTE_PRODUTO INT AUTO_INCREMENT PRIMARY KEY,
  ID_PRODUTO INT NOT NULL,
  ID_COMPRA INT NOT NULL,
  DT_VALIDADE DATE NOT NULL,
  QT_RECEBIDA INT NOT NULL,
  VL_CUSTO_UNITARIO decimal(10,2) NOT NULL,
  CONSTRAINT fk_lote_produto_produto FOREIGN KEY (ID_PRODUTO) REFERENCES PRODUTO(ID_PRODUTO),
  CONSTRAINT fk_lote_produto_compra FOREIGN KEY (ID_COMPRA) REFERENCES COMPRA(ID_COMPRA),
  CONSTRAINT ck_lote_produto_qt_recebida CHECK (QT_RECEBIDA > 0),
  CONSTRAINT ck_lote_produto_vl_custo_unitario CHECK (VL_CUSTO_UNITARIO >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- =====================================================================
-- Passo 4: INSERT INTO — massa de dados FICTÍCIA (nomes, CPFs e contatos inventados; gerada com semente fixa)
-- =====================================================================
-- ALUNO: 850 registros
-- PLANO: 5 registros
-- PROMOCAO: 6 registros
-- CONTRATO: 2088 registros
-- TRANCAMENTO: 17 registros
-- CANCELAMENTO: 29 registros
-- NOTIFICACAO: 109 registros
-- PERFIL: 3 registros
-- PERMISSAO: 18 registros
-- PERFIL_PERMISSAO: 32 registros
-- FUNCIONARIO: 19 registros
-- PROFESSOR: 14 registros
-- ESCALA_TRABALHO: 19 registros
-- PONTO: 228 registros
-- AVALIACAO_FISICA: 170 registros
-- FICHA_TREINO: 751 registros
-- TREINO: 2253 registros
-- EXERCICIO: 40 registros
-- TREINO_EXERCICIO: 9012 registros
-- REGISTRO_CARGA: 2243 registros
-- MODALIDADE: 2 registros
-- AULA_COLETIVA: 12 registros
-- AGENDAMENTO_AULA: 510 registros
-- PRODUTO: 24 registros
-- FORNECEDOR: 9 registros
-- VENDA: 288 registros
-- ITEM_VENDA: 542 registros
-- EQUIPAMENTO: 70 registros
-- ROTINA_MANUTENCAO: 15 registros
-- INSPECAO_EQUIPAMENTO: 696 registros
-- INCIDENTE_SEGURANCA: 6 registros
-- ASSISTENCIA_TECNICA: 1 registros
-- COBRANCA: 2376 registros
-- PAGAMENTO: 2347 registros
-- NOTA_FISCAL: 2314 registros
-- REGISTRO_ACESSO: 2816 registros
-- COMPRA: 18 registros
-- EXECUCAO_MANUTENCAO: 260 registros
-- CHAMADO_TECNICO: 31 registros
-- PECA_TROCADA: 25 registros
-- LOTE_PRODUTO: 88 registros

-- =====================================================================
-- Datas de referência das consultas (a massa de dados foi gerada para "hoje" = 28/10/2026)
-- =====================================================================
SET @hoje = '2026-10-28';
SET @ate7 = '2026-11-04';
SET @ate30 = '2026-11-27';
SET @ate60 = '2026-12-27';
SET @ha60 = '2026-08-29';
SET @ha14 = '2026-10-14';

-- =====================================================================
-- Passo 5: SELECT com JOIN (consultas que cruzam várias tabelas)
-- =====================================================================
-- J01 — Quais são os contratos vigentes, com aluno e plano?
SELECT c.ID_CONTRATO, a.NM_ALUNO, p.TP_PLANO, c.DT_INICIO, c.DT_FIM, c.TP_SITUACAO
FROM CONTRATO c
JOIN ALUNO a ON a.ID_ALUNO = c.ID_ALUNO
JOIN PLANO p ON p.ID_PLANO = c.ID_PLANO
WHERE c.TP_SITUACAO = 'vigente'
ORDER BY c.DT_FIM
LIMIT 20;

-- J02 — Quais aulas coletivas existem, com modalidade, professor e horário?
SELECT m.NM_MODALIDADE, ac.TP_DIA_SEMANA, ac.HR_INICIO, f.NM_FUNCIONARIO AS professor, ac.QT_CAPACIDADE_MAXIMA
FROM AULA_COLETIVA ac
JOIN MODALIDADE m ON m.ID_MODALIDADE = ac.ID_MODALIDADE
JOIN PROFESSOR pr ON pr.ID_PROFESSOR = ac.ID_PROFESSOR
JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = pr.ID_FUNCIONARIO
ORDER BY m.NM_MODALIDADE, ac.HR_INICIO;

-- J03 — Quais produtos foram vendidos em cada venda, e por quem?
SELECT v.ID_VENDA, v.DT_VENDA, f.NM_FUNCIONARIO AS vendedor, pr.NM_PRODUTO, i.QT_VENDIDA, i.VL_PRECO_UNITARIO
FROM VENDA v
JOIN ITEM_VENDA i ON i.ID_VENDA = v.ID_VENDA
JOIN PRODUTO pr ON pr.ID_PRODUTO = i.ID_PRODUTO
JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = v.ID_FUNCIONARIO
ORDER BY v.DT_VENDA DESC
LIMIT 20;

-- J04 — Quais equipamentos têm chamado técnico em aberto, com a assistência acionada?
SELECT e.NM_EQUIPAMENTO, e.DS_LOCALIZACAO, ch.DT_ABERTURA, ch.TP_SITUACAO, at.NM_EMPRESA
FROM CHAMADO_TECNICO ch
JOIN EQUIPAMENTO e ON e.ID_EQUIPAMENTO = ch.ID_EQUIPAMENTO
JOIN ASSISTENCIA_TECNICA at ON at.ID_ASSISTENCIA_TECNICA = ch.ID_ASSISTENCIA_TECNICA
WHERE ch.TP_SITUACAO <> 'concluido';

-- =====================================================================
-- Passo 6: UPDATE
-- =====================================================================
-- U01 — Bloquear alunos com cobrança atrasada há mais de 5 dias (RN02; resolve P1/P2 na origem do status)
UPDATE ALUNO
SET TP_SITUACAO = 'bloqueado'
WHERE TP_SITUACAO = 'ativo'
  AND ID_ALUNO IN (SELECT c.ID_ALUNO
                   FROM CONTRATO c
                   JOIN COBRANCA cb ON cb.ID_CONTRATO = c.ID_CONTRATO
                   WHERE cb.TP_SITUACAO = 'atrasada' AND DATEDIFF(@hoje, cb.DT_VENCIMENTO) > 5);

-- U02 — Concluir o chamado em atendimento: teste de carga aprovado e liberação autorizada pelo coordenador (RN23)
UPDATE CHAMADO_TECNICO
SET IN_TESTE_CARGA_APROVADO = 1, DT_LIBERACAO = '2026-10-28 09:30:00', TP_SITUACAO = 'concluido', ID_FUNCIONARIO = 6
WHERE ID_CHAMADO_TECNICO = 29;

-- U03 — Voltar o equipamento do chamado concluído para operacional
UPDATE EQUIPAMENTO SET TP_SITUACAO = 'operacional' WHERE ID_EQUIPAMENTO = 5;

-- =====================================================================
-- Passo 7: DELETE (apaga apenas um cadastro de teste, sem vínculos)
-- =====================================================================
VALUES ('00000000000', '00000000', 'Cadastro de Teste', '1990-01-01', '11900000000', '08452105', 'teste@exemplo.com.br', 'ativo');
-- D01 — Excluir o cadastro de teste (um aluno com contratos não pode ser apagado: as FKs impedem; o histórico é preservado)
DELETE FROM ALUNO WHERE ID_CPF = '00000000000';

-- =====================================================================
-- Passo 8: CONSULTAS GERENCIAIS (G01…)
-- =====================================================================
-- G01 — Quantos acessos permitidos houve, por dia, para alunos bloqueados nos últimos 14 dias?
-- Atende: P1 (catraca libera quem não pagou)
SELECT DATE(ra.DT_ACESSO) AS dia, COUNT(*) AS acessos_indevidos
FROM REGISTRO_ACESSO ra
JOIN ALUNO a ON a.ID_ALUNO = ra.ID_ALUNO
WHERE ra.TP_RESULTADO = 'permitido' AND a.TP_SITUACAO = 'bloqueado' AND DATE(ra.DT_ACESSO) >= @ha14
GROUP BY DATE(ra.DT_ACESSO)
ORDER BY dia;

-- G02 — Quais alunos estão inadimplentes, quanto devem e há quantos dias? (lista para a gerente cobrar)
-- Atende: P2 (cobrança manual de inadimplentes)
SELECT a.NM_ALUNO, a.NR_CELULAR, a.TP_SITUACAO, cb.VL_COBRANCA AS valor_em_atraso, cb.DT_VENCIMENTO, DATEDIFF(@hoje, cb.DT_VENCIMENTO) AS dias_em_atraso
FROM COBRANCA cb
JOIN CONTRATO c ON c.ID_CONTRATO = cb.ID_CONTRATO
JOIN ALUNO a ON a.ID_ALUNO = c.ID_ALUNO
WHERE cb.TP_SITUACAO = 'atrasada'
ORDER BY dias_em_atraso DESC;

-- G03 — Quanto foi recebido por mês, por forma de pagamento?
-- Atende: P3 (controle financeiro em planilhas) e KPI receita mensal
SELECT DATE_FORMAT(p.DT_PAGAMENTO, '%Y-%m') AS mes, p.TP_FORMA, COUNT(*) AS pagamentos, SUM(p.VL_PAGO) AS total_recebido
FROM PAGAMENTO p
GROUP BY DATE_FORMAT(p.DT_PAGAMENTO, '%Y-%m'), p.TP_FORMA
ORDER BY mes, p.TP_FORMA;

-- G04 — Quais lotes de suplementos estão vencidos ou vencem em 30 dias?
-- Atende: P4 (validade controlada manualmente)
SELECT pr.NM_PRODUTO, l.ID_LOTE_PRODUTO, l.DT_VALIDADE, l.QT_RECEBIDA,
       CASE WHEN l.DT_VALIDADE < @hoje THEN 'vencido' ELSE 'vence em 30 dias' END AS situacao
FROM LOTE_PRODUTO l
JOIN PRODUTO pr ON pr.ID_PRODUTO = l.ID_PRODUTO
WHERE l.DT_VALIDADE <= @ate30
ORDER BY l.DT_VALIDADE;

-- G05 — Quantos equipamentos estão operacionais e interditados, por categoria?
-- Atende: P5 (sem visão da situação das máquinas)
SELECT e.TP_CATEGORIA, e.TP_SITUACAO, COUNT(*) AS equipamentos
FROM EQUIPAMENTO e
GROUP BY e.TP_CATEGORIA, e.TP_SITUACAO
ORDER BY e.TP_CATEGORIA, e.TP_SITUACAO;

-- G06 — Qual o histórico de defeitos por equipamento (chamados, dias parado e custo)?
-- Atende: P5 e KPI defeitos por equipamento (apoia a decisão de substituir)
SELECT e.ID_EQUIPAMENTO, e.NM_EQUIPAMENTO, e.TP_CATEGORIA, COUNT(ch.ID_CHAMADO_TECNICO) AS chamados,
       ROUND(SUM(DATEDIFF(ch.DT_LIBERACAO, ch.DT_ABERTURA)), 1) AS dias_parado,
       COALESCE(SUM(ch.VL_CUSTO_SERVICO), 0) AS custo_servico
FROM EQUIPAMENTO e
JOIN CHAMADO_TECNICO ch ON ch.ID_EQUIPAMENTO = e.ID_EQUIPAMENTO
GROUP BY e.ID_EQUIPAMENTO, e.NM_EQUIPAMENTO, e.TP_CATEGORIA
HAVING COUNT(ch.ID_CHAMADO_TECNICO) >= 2
ORDER BY chamados DESC, custo_servico DESC;

-- G07 — Quais garantias de equipamentos vencem nos próximos 60 dias ou já venceram há menos de 60 dias?
-- Atende: P6 (garantias sem alerta)
SELECT e.NM_EQUIPAMENTO, e.TP_CATEGORIA, e.DT_AQUISICAO, e.DT_FIM_GARANTIA, DATEDIFF(e.DT_FIM_GARANTIA, @hoje) AS dias_para_vencer
FROM EQUIPAMENTO e
WHERE e.DT_FIM_GARANTIA BETWEEN @ha60 AND @ate60
ORDER BY e.DT_FIM_GARANTIA;

-- G08 — Quais equipamentos estão com a revisão técnica atrasada (mais de 30 dias na musculação, mais de 15 nos aeróbicos)?
-- Atende: P6 (revisões sem alerta)
SELECT e.NM_EQUIPAMENTO, e.TP_CATEGORIA, MAX(x.DT_EXECUCAO) AS ultima_revisao, DATEDIFF(@hoje, MAX(x.DT_EXECUCAO)) AS dias_sem_revisao
FROM EQUIPAMENTO e
JOIN EXECUCAO_MANUTENCAO x ON x.ID_EQUIPAMENTO = e.ID_EQUIPAMENTO
JOIN ROTINA_MANUTENCAO r ON r.ID_ROTINA_MANUTENCAO = x.ID_ROTINA_MANUTENCAO AND r.TP_EXECUTOR = 'empresa_terceirizada'
GROUP BY e.ID_EQUIPAMENTO, e.NM_EQUIPAMENTO, e.TP_CATEGORIA
HAVING DATEDIFF(@hoje, MAX(x.DT_EXECUCAO)) > CASE WHEN e.TP_CATEGORIA IN ('maquina', 'peso_livre') THEN 30 ELSE 15 END
ORDER BY dias_sem_revisao DESC;

-- G09 — Quanto se gastou com manutenção por mês (serviços e peças)?
-- Atende: P7 (custos de manutenção dispersos) e KPI gasto de manutenção
SELECT mes, SUM(servico) AS servicos, SUM(pecas) AS pecas, SUM(servico) + SUM(pecas) AS total
FROM (SELECT DATE_FORMAT(ch.DT_ABERTURA, '%Y-%m') AS mes, COALESCE(ch.VL_CUSTO_SERVICO, 0) AS servico, 0 AS pecas
      FROM CHAMADO_TECNICO ch
      UNION ALL
      SELECT DATE_FORMAT(ch.DT_ABERTURA, '%Y-%m'), 0, pt.QT_PECA * pt.VL_CUSTO_UNITARIO
      FROM PECA_TROCADA pt JOIN CHAMADO_TECNICO ch ON ch.ID_CHAMADO_TECNICO = pt.ID_CHAMADO_TECNICO) t
GROUP BY mes
ORDER BY mes;

-- G10 — Qual a taxa de cancelamento por mês (cancelamentos ÷ contratos iniciados até o mês)?
-- KPI: taxa de cancelamento mensal (meta sugerida: abaixo de 2%)
SELECT m.mes, m.cancelamentos,
       (SELECT COUNT(*) FROM CONTRATO c2 WHERE c2.DT_INICIO <= m.ultimo_dia) AS contratos_ate_o_mes,
       ROUND(100.0 * m.cancelamentos / (SELECT COUNT(*) FROM CONTRATO c3 WHERE c3.DT_INICIO <= m.ultimo_dia), 2) AS taxa_percentual
FROM (SELECT DATE_FORMAT(cn.DT_CANCELAMENTO, '%Y-%m') AS mes, COUNT(*) AS cancelamentos, MAX(cn.DT_CANCELAMENTO) AS ultimo_dia
      FROM CANCELAMENTO cn
      GROUP BY DATE_FORMAT(cn.DT_CANCELAMENTO, '%Y-%m')) m
ORDER BY m.mes;

-- G11 — Quanto cada plano arrecadou e qual o valor médio por pagamento?
-- KPI: receita e ticket médio por plano
SELECT pl.TP_PLANO, COUNT(p.ID_PAGAMENTO) AS pagamentos, SUM(p.VL_PAGO) AS receita, ROUND(AVG(p.VL_PAGO), 2) AS ticket_medio
FROM PAGAMENTO p
JOIN COBRANCA cb ON cb.ID_COBRANCA = p.ID_COBRANCA
JOIN CONTRATO c ON c.ID_CONTRATO = cb.ID_CONTRATO
JOIN PLANO pl ON pl.ID_PLANO = c.ID_PLANO
GROUP BY pl.TP_PLANO
ORDER BY receita DESC;

-- G12 — Qual a ocupação média das aulas coletivas por modalidade (agendados ÷ 30 vagas)?
-- KPI: taxa de ocupação das aulas (meta sugerida: acima de 60%)
SELECT m.NM_MODALIDADE, COUNT(*) AS sessoes, ROUND(AVG(s.agendados), 1) AS media_agendados,
       ROUND(100.0 * AVG(s.agendados) / MAX(s.QT_CAPACIDADE_MAXIMA), 1) AS ocupacao_percentual
FROM (SELECT ag.ID_AULA_COLETIVA, ag.DT_AULA, COUNT(*) AS agendados, MAX(ac.QT_CAPACIDADE_MAXIMA) AS QT_CAPACIDADE_MAXIMA, MAX(ac.ID_MODALIDADE) AS ID_MODALIDADE
      FROM AGENDAMENTO_AULA ag JOIN AULA_COLETIVA ac ON ac.ID_AULA_COLETIVA = ag.ID_AULA_COLETIVA
      GROUP BY ag.ID_AULA_COLETIVA, ag.DT_AULA) s
JOIN MODALIDADE m ON m.ID_MODALIDADE = s.ID_MODALIDADE
GROUP BY m.NM_MODALIDADE;

-- G13 — Quantos acessos permitidos por aluno ativo, por semana, nos últimos 14 dias?
-- KPI: frequência média semanal
SELECT ROUND(COUNT(*) / 2.0 / (SELECT COUNT(*) FROM ALUNO WHERE TP_SITUACAO = 'ativo'), 2) AS acessos_por_aluno_por_semana
FROM REGISTRO_ACESSO ra
WHERE ra.TP_RESULTADO = 'permitido' AND DATE(ra.DT_ACESSO) >= @ha14;

-- G14 — Qual o tempo médio de parada (horas entre a abertura do chamado e a liberação), por mês?
-- KPI: tempo médio de parada (referência: 48 horas)
SELECT DATE_FORMAT(ch.DT_ABERTURA, '%Y-%m') AS mes, COUNT(*) AS chamados,
       ROUND(AVG(TIMESTAMPDIFF(HOUR, ch.DT_ABERTURA, ch.DT_LIBERACAO)), 1) AS horas_medias_parado
FROM CHAMADO_TECNICO ch
WHERE ch.DT_LIBERACAO IS NOT NULL
GROUP BY DATE_FORMAT(ch.DT_ABERTURA, '%Y-%m')
ORDER BY mes;

-- G15 — Quais equipamentos têm cabo ou estofado em condição de atenção ou ruim na última inspeção?
-- KPI: condição de cabos e estofados (informação mais importante para a gerência)
SELECT e.NM_EQUIPAMENTO, i.TP_COMPONENTE, i.TP_CONDICAO, i.DT_INSPECAO
FROM INSPECAO_EQUIPAMENTO i
JOIN EQUIPAMENTO e ON e.ID_EQUIPAMENTO = i.ID_EQUIPAMENTO
WHERE i.TP_COMPONENTE IN ('cabo', 'estofado') AND i.TP_CONDICAO <> 'boa'
  AND i.DT_INSPECAO = (SELECT MAX(i2.DT_INSPECAO) FROM INSPECAO_EQUIPAMENTO i2 WHERE i2.ID_EQUIPAMENTO = i.ID_EQUIPAMENTO AND i2.TP_COMPONENTE = i.TP_COMPONENTE)
ORDER BY e.NM_EQUIPAMENTO;

-- G16 — Quais suplementos mais venderam e qual o saldo de estoque (recebido − vendido)?
-- KPI: produtos mais vendidos e produtos com saldo baixo (menos de 10 unidades)
SELECT pr.NM_PRODUTO,
       COALESCE((SELECT SUM(i.QT_VENDIDA) FROM ITEM_VENDA i WHERE i.ID_PRODUTO = pr.ID_PRODUTO), 0) AS vendido,
       COALESCE((SELECT SUM(l.QT_RECEBIDA) FROM LOTE_PRODUTO l WHERE l.ID_PRODUTO = pr.ID_PRODUTO), 0)
       - COALESCE((SELECT SUM(i.QT_VENDIDA) FROM ITEM_VENDA i WHERE i.ID_PRODUTO = pr.ID_PRODUTO), 0) AS saldo
FROM PRODUTO pr
ORDER BY saldo ASC, vendido DESC
LIMIT 10;

-- G17 — Quais fichas de treino já passaram da data prevista de troca (a cada 3 meses)?
-- KPI: treinos a trocar (RF27)
SELECT a.NM_ALUNO, ft.DT_CRIACAO, ft.DT_TROCA_PREVISTA, DATEDIFF(@hoje, ft.DT_TROCA_PREVISTA) AS dias_de_atraso
FROM FICHA_TREINO ft
JOIN ALUNO a ON a.ID_ALUNO = ft.ID_ALUNO
WHERE ft.DT_TROCA_PREVISTA < @hoje
ORDER BY dias_de_atraso DESC
LIMIT 20;

-- G18 — Quantas avaliações físicas cada professor realizou, por mês?
-- KPI: avaliações por professor
SELECT f.NM_FUNCIONARIO AS professor, DATE_FORMAT(av.DT_AVALIACAO, '%Y-%m') AS mes, COUNT(*) AS avaliacoes
FROM AVALIACAO_FISICA av
JOIN PROFESSOR pr ON pr.ID_PROFESSOR = av.ID_PROFESSOR
JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = pr.ID_FUNCIONARIO
WHERE av.TP_SITUACAO = 'realizada'
GROUP BY f.NM_FUNCIONARIO, DATE_FORMAT(av.DT_AVALIACAO, '%Y-%m')
ORDER BY mes, avaliacoes DESC;

-- =====================================================================
-- Passo 9: CONSULTAS DE AUDITORIA (A01…) — o resultado ideal é "nenhuma linha", exceto onde o texto indica o contrário
-- =====================================================================
-- A01 — Existe acesso permitido a aluno bloqueado ou sem contrato vigente na data do acesso?
-- Verifica: RN03 (a catraca bloqueia aluno bloqueado ou com plano encerrado) — aponta a falha atual da catraca (P1)
SELECT ra.ID_REGISTRO_ACESSO, a.NM_ALUNO, a.TP_SITUACAO, ra.DT_ACESSO, ra.TP_METODO
FROM REGISTRO_ACESSO ra
JOIN ALUNO a ON a.ID_ALUNO = ra.ID_ALUNO
WHERE ra.TP_RESULTADO = 'permitido' AND ra.TP_METODO <> 'manual'
  AND (a.TP_SITUACAO = 'bloqueado'
       OR NOT EXISTS (SELECT 1 FROM CONTRATO c
                      WHERE c.ID_ALUNO = a.ID_ALUNO AND c.TP_SITUACAO IN ('vigente', 'encerrado')
                        AND DATE(ra.DT_ACESSO) BETWEEN c.DT_INICIO AND c.DT_FIM))
ORDER BY ra.DT_ACESSO;

-- A02 — Existe aluno menor de 18 anos sem telefone do responsável?
-- Verifica: RN01
SELECT a.ID_ALUNO, a.NM_ALUNO, a.DT_NASCIMENTO
FROM ALUNO a
WHERE TIMESTAMPDIFF(YEAR, a.DT_NASCIMENTO, @hoje) < 18 AND a.NR_TELEFONE_RESPONSAVEL IS NULL;

-- A03 — Existe trancamento com mais de 3 meses?
-- Verifica: RN06 (aproximação: mais de 92 dias)
SELECT t.ID_TRANCAMENTO, t.ID_CONTRATO, t.DT_INICIO, t.DT_FIM
FROM TRANCAMENTO t
WHERE DATEDIFF(t.DT_FIM, t.DT_INICIO) > 92;

-- A04 — Existe cobrança sem contrato e sem venda, ou com os dois?
-- Verifica: RN11
SELECT cb.ID_COBRANCA
FROM COBRANCA cb
WHERE (cb.ID_CONTRATO IS NULL AND cb.ID_VENDA IS NULL) OR (cb.ID_CONTRATO IS NOT NULL AND cb.ID_VENDA IS NOT NULL);

-- A05 — Existe aula com mais de 30 agendamentos na mesma data?
-- Verifica: RN14 (capacidade)
SELECT ag.ID_AULA_COLETIVA, ag.DT_AULA, COUNT(*) AS agendados
FROM AGENDAMENTO_AULA ag
JOIN AULA_COLETIVA ac ON ac.ID_AULA_COLETIVA = ag.ID_AULA_COLETIVA
GROUP BY ag.ID_AULA_COLETIVA, ag.DT_AULA, ac.QT_CAPACIDADE_MAXIMA
HAVING COUNT(*) > ac.QT_CAPACIDADE_MAXIMA;

-- A06 — Existe agendamento feito com menos de 20 minutos de antecedência?
-- Verifica: RN14 (agendamento até 20 minutos antes)
SELECT ag.ID_AGENDAMENTO_AULA, ag.DT_AGENDAMENTO, ag.DT_AULA
FROM AGENDAMENTO_AULA ag
WHERE TIMESTAMPDIFF(MINUTE, ag.DT_AGENDAMENTO, ag.DT_AULA) < 20;

-- A07 — Existe equipamento operacional com chamado não concluído, ou interditado sem chamado em andamento?
-- Verifica: RN23 (interdição imediata até o reparo)
SELECT e.ID_EQUIPAMENTO, e.NM_EQUIPAMENTO, e.TP_SITUACAO
FROM EQUIPAMENTO e
WHERE (e.TP_SITUACAO = 'operacional' AND EXISTS (SELECT 1 FROM CHAMADO_TECNICO ch WHERE ch.ID_EQUIPAMENTO = e.ID_EQUIPAMENTO AND ch.TP_SITUACAO <> 'concluido'))
   OR (e.TP_SITUACAO = 'interditado' AND NOT EXISTS (SELECT 1 FROM CHAMADO_TECNICO ch WHERE ch.ID_EQUIPAMENTO = e.ID_EQUIPAMENTO AND ch.TP_SITUACAO <> 'concluido'));

-- A08 — Existe chamado concluído sem teste de carga aprovado ou sem autorizador da liberação?
-- Verifica: RN23 e RN28 (liberação só após teste de carga, autorizada pelo coordenador)
SELECT ch.ID_CHAMADO_TECNICO, ch.ID_EQUIPAMENTO, ch.IN_TESTE_CARGA_APROVADO, ch.ID_FUNCIONARIO
FROM CHAMADO_TECNICO ch
WHERE ch.TP_SITUACAO = 'concluido' AND (ch.IN_TESTE_CARGA_APROVADO IS NULL OR ch.IN_TESTE_CARGA_APROVADO = 0 OR ch.ID_FUNCIONARIO IS NULL);

-- A09 — Existe jornada de professor com saída antes da entrada ou acima de 6 horas?
-- Verifica: RN17 e RN21 (jornada de 5 horas por dia)
SELECT p.ID_PONTO, f.NM_FUNCIONARIO, p.DT_ENTRADA, p.DT_SAIDA
FROM PONTO p
JOIN FUNCIONARIO f ON f.ID_FUNCIONARIO = p.ID_FUNCIONARIO
JOIN PROFESSOR pr ON pr.ID_FUNCIONARIO = f.ID_FUNCIONARIO
WHERE p.DT_SAIDA < p.DT_ENTRADA OR TIMESTAMPDIFF(HOUR, p.DT_ENTRADA, p.DT_SAIDA) > 6;

-- A10 — Existe contrato vigente que termina em até 7 dias sem aviso de término enviado?
-- Verifica: RN04 (aviso 7 dias antes do término)
SELECT c.ID_CONTRATO, a.NM_ALUNO, c.DT_FIM
FROM CONTRATO c
JOIN ALUNO a ON a.ID_ALUNO = c.ID_ALUNO
WHERE c.TP_SITUACAO = 'vigente' AND c.DT_FIM BETWEEN @hoje AND @ate7
  AND NOT EXISTS (SELECT 1 FROM NOTIFICACAO n WHERE n.ID_ALUNO = c.ID_ALUNO AND n.TP_NOTIFICACAO = 'termino_plano')
ORDER BY c.DT_FIM;

-- A11 — Existe cobrança paga cujos pagamentos não somam o valor devido?
-- Verifica: RN33 (pagamentos de cobrança paga somam o valor devido)
SELECT cb.ID_COBRANCA, cb.VL_COBRANCA, SUM(p.VL_PAGO) AS pago
FROM COBRANCA cb
JOIN PAGAMENTO p ON p.ID_COBRANCA = cb.ID_COBRANCA
WHERE cb.TP_SITUACAO = 'paga'
GROUP BY cb.ID_COBRANCA, cb.VL_COBRANCA
HAVING SUM(p.VL_PAGO) <> cb.VL_COBRANCA;

-- A12 — Existe venda ou compra cujo total não bate com a soma dos itens/lotes?
-- Verifica: RN31 e RN32 (totais derivados) 
SELECT 'venda' AS origem, v.ID_VENDA AS id, v.VL_TOTAL AS total_registrado, ROUND(SUM(i.QT_VENDIDA * i.VL_PRECO_UNITARIO), 2) AS total_calculado
FROM VENDA v JOIN ITEM_VENDA i ON i.ID_VENDA = v.ID_VENDA
GROUP BY v.ID_VENDA, v.VL_TOTAL
HAVING ABS(v.VL_TOTAL - ROUND(SUM(i.QT_VENDIDA * i.VL_PRECO_UNITARIO), 2)) > 0.01
UNION ALL
SELECT 'compra', c.ID_COMPRA, c.VL_TOTAL, ROUND(SUM(l.QT_RECEBIDA * l.VL_CUSTO_UNITARIO), 2)
FROM COMPRA c JOIN LOTE_PRODUTO l ON l.ID_COMPRA = c.ID_COMPRA
GROUP BY c.ID_COMPRA, c.VL_TOTAL
HAVING ABS(c.VL_TOTAL - ROUND(SUM(l.QT_RECEBIDA * l.VL_CUSTO_UNITARIO), 2)) > 0.01;

-- A13 — Existe funcionário com perfil de professor sem registro em PROFESSOR?
-- Verifica: RN15 (professores são funcionários contratados para a função)
SELECT f.ID_FUNCIONARIO, f.NM_FUNCIONARIO
FROM FUNCIONARIO f
JOIN PERFIL pf ON pf.ID_PERFIL = f.ID_PERFIL
WHERE pf.NM_PERFIL = 'professor' AND NOT EXISTS (SELECT 1 FROM PROFESSOR pr WHERE pr.ID_FUNCIONARIO = f.ID_FUNCIONARIO);
